// Project data layer.
//
// · src/data/repos.json — generated by `npm run fetch:repos`, never hand-edited
// · CURATED below        — hand-written copy: Chinese blurbs, display titles, roles, tags
//
// Cards render from the union of both, so a repo with no README still gets real copy.

import generated from './repos.js';
import { langColor } from '../lib/icons.js';

/** Per-repo overrides. Keys are repo names. Add an entry whenever you want better copy. */
const CURATED = {
  waw: {
    title: 'waw',
    blurb: '这个作品集本身：零依赖的静态站，手写 CSS 设计系统，Node 脚本完成构建与部署。',
    note: '没有打包器，没有框架，没有前置二进制。',
    role: '设计与开发',
    category: 'web',
    tags: ['vanilla-js', 'static-site', 'design-system'],
  },
};

const FALLBACK = {
  title: (name) => name,
  blurb: (repo) => repo.description || repo.readmeSummary || '',
  role: '作者',
  tags: [],
};

/** Category → display label, used by the projects page filter. */
export const CATEGORY_LABELS = {
  web: 'Web 与界面',
  ai: 'AI 与模型',
  tool: '工具与脚本',
  study: '学习与实验',
  other: '其它',
};

function inferCategory(repo) {
  const text = `${repo.name} ${repo.description ?? ''} ${(repo.topics ?? []).join(' ')}`.toLowerCase();
  if (/(portfolio|site|web|ui|frontend|css|html)/.test(text)) return 'web';
  if (/(ai|llm|model|ml|pytorch|tensorflow|neural|cnn|transformer|nlp|dataset|train)/.test(text)) return 'ai';
  if (/(cli|tool|script|bot|automation|util)/.test(text)) return 'tool';
  if (/(learn|study|note|demo|test|try|practice|homework)/.test(text)) return 'study';
  return 'other';
}

function toProject(repo) {
  const curated = CURATED[repo.name] ?? {};
  const isProfileRepo = Boolean(repo.isProfileRepo);

  return {
    name: repo.name,
    title: curated.title ?? FALLBACK.title(repo.name),
    url: repo.url ?? '',
    homepage: repo.homepage || null,
    blurb: curated.blurb ?? FALLBACK.blurb(repo),
    note: curated.note ?? '',
    language: repo.language ?? null,
    langColor: langColor(repo.language),
    tags: curated.tags ?? repo.topics ?? FALLBACK.tags,
    stars: repo.stars ?? 0,
    forks: repo.forks ?? 0,
    createdAt: repo.createdAt ?? '',
    updatedAt: repo.updatedAt ?? '',
    role: curated.role ?? FALLBACK.role,
    category: curated.category ?? inferCategory(repo),
    isProfileRepo,
  };
}

let cache = null;

/** All projects, hidden profile repos excluded unless they are the only thing available. */
export async function loadProjects() {
  if (cache) return cache;
  const user = generated.user ?? {};
  const repos = generated.repos ?? [];

  const avatar = user.avatar ?? null;
  if (avatar) {
    // Expose the real avatar to the shell without a second request.
    globalThis.__SITE__ = { ...globalThis.__SITE__, avatar };
  }

  const visible = repos.filter((r) => !r.isProfileRepo);
  const source = visible.length ? visible : repos;

  cache = source.map(toProject);
  return cache;
}

export function stats(projects) {
  const languages = new Set(projects.map((p) => p.language).filter(Boolean));
  const stars = projects.reduce((sum, p) => sum + (p.stars ?? 0), 0);
  const latest = projects
    .map((p) => p.updatedAt)
    .filter(Boolean)
    .sort()
    .at(-1);

  const days = latest ? Math.round((Date.now() - new Date(latest).getTime()) / 86_400_000) : null;
  const updatedLabel = days === null ? '—' : days <= 1 ? '今天' : days < 30 ? `${days} 天前` : `${Math.round(days / 30)} 个月前`;

  // A bare "0" reads like a bug; "—" reads like "nothing to count yet".
  return {
    total: projects.length,
    languages: languages.size,
    languagesLabel: languages.size ? String(languages.size) : '—',
    stars,
    starsLabel: stars ? String(stars) : '—',
    updatedLabel,
    latest,
  };
}

export function generatedAt() {
  return generated.generatedAt ?? null;
}

export function profile() {
  return generated.user ?? {};
}
